🐛 Describe the bug
PyTorch Teams:
I hope this message finds you well. I have been using the PyTorch JIT module for deploying and inferring deep learning models on my Windows Server 2019 system with two AMD EPYC 7543F processors and 512GB of memory. I have encountered an issue related to the performance of the JIT module after calling the cudaHostRegister function from CUDA. The libtorch I'm using is the libtorch bundled in 1.13.0+cu116.
To provide some context, I have observed that the JIT module performs well when I don't invoke cudaHostRegister. However, when I do call cudaHostRegister to register 1GB of memory, the overall performance of JIT inference slows down significantly. Theoretically, since I'm registering a relatively small amount of memory, it should not impact the system's performance or PyTorch's memory allocator.
Here's the cpp code I used:
#pragma warning(push, 0)
#include <torch/torch.h>
#include <torch/script.h>
#pragma warning(pop)
#include <pybind11/embed.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <numpy/arrayobject.h>
#include <cuda_runtime.h>
#include <spdlog/spdlog.h>
#include <spdlog/stopwatch.h>
#include <Windows.h>
int main() {
    {
        ULONGLONG size;
        GetNumaAvailableMemoryNode(0, &size);
        spdlog::info("Available memory on numa node 0 {}GB", size / 1e9);
        GetNumaAvailableMemoryNode(1, &size);
        spdlog::info("Available memory on numa node 1 {}GB", size / 1e9);
    }
    pybind11::scoped_interpreter guard{};
    pybind11::module_::import("torch");
    pybind11::exec("import torch;print(torch.__version__)");
    const int segDID = 1;
    const int bumpDID = 2;
    size_t s = (size_t) 1 * 1024 * 1024 * 1024;
    void *ptr = malloc(s);
    auto e = cudaHostRegister(ptr, s, cudaHostRegisterDefault);
    if (e != cudaSuccess) {
        spdlog::info("{}", e);
        std::abort();
    }
    c10::InferenceMode guard1;
    torch::jit::script::Module module =
      torch::jit::load(R"(C:\Users\kohill.WIN-5VEFDUPJLBO\Desktop\segment0727.pt)");
    module.eval();
    module.to(torch::Device(torch::kCUDA, segDID));
    for (int ii = 0; ii < 4; ++ii) {
        spdlog::stopwatch sw;
        for (int i = 0; i < 400; ++i) {
            torch::Tensor x =
              torch::zeros({1, 3, 896, 1088},
                           torch::TensorOptions().device(torch::kCUDA, segDID).dtype(torch::kF32));
            module.forward({x}).toTensor();
            torch::cuda::synchronize(segDID);
        }
        spdlog::info("inference took {}s", sw);
    }
    torch::jit::script::Module bumpmodule =
      torch::jit::load(R"(C:\Users\kohill.WIN-5VEFDUPJLBO\Desktop\backbump0808_2.pt)");
    bumpmodule.eval();
    bumpmodule.to(torch::Device(torch::kCUDA, bumpDID));
    for (int ii = 0; ii < 2; ++ii) {
        spdlog::stopwatch sw;
        for (int i = 0; i < 400; ++i) {
            torch::Tensor x =
              torch::zeros({1, 3, 896, 1088},
                           torch::TensorOptions().device(torch::kCUDA, bumpDID).dtype(torch::kF32));
            bumpmodule.forward({x}).toTensor();
            torch::cuda::synchronize(bumpDID);
        }
        spdlog::info("bump inference took {}s", sw);
    }
    for (int ii = 0; ii < 4; ++ii) {
        spdlog::stopwatch sw;
        for (int i = 0; i < 400; ++i) {
            torch::Tensor x =
              torch::zeros({1, 3, 896, 1088},
                           torch::TensorOptions().device(torch::kCUDA, segDID).dtype(torch::kF32));
            module.forward({x}).toTensor();
            torch::cuda::synchronize(segDID);
        }
        spdlog::info("inference took {}s", sw);
    }
    system("pause");
    return 0;
}
And here's the outputs, after loading the second model on a different GPU, the inference time of the same model increases from 4.10 seconds to 19.04 seconds.
